prompt:
Parallelize the C program below with OpenMP so that it runs as fast as possible.
Rules:
- Change only the code between the "=== KERNEL BEGIN ===" and "=== KERNEL END ===" markers.
  You may add #include lines at the top of the file.
- Keep main(), the function signature of kernel(), and the output line unchanged.
- The program must give the same result as the serial version.
- It will be compiled with: clang -O2 -fopenmp (OpenMP 5.1) and run with
  OMP_NUM_THREADS set to each value from 1 to 10.

Target machine: Apple M4 (MacBook Air, macOS). Its 10 CPU cores are not identical:
4 performance cores (P-cores) and 6 efficiency cores (E-cores), which are slower.
The operating system decides which core each thread runs on; threads cannot be
pinned to specific cores.

Reply with the complete modified program in a single ```c code block.

The program includes "common.h", shown first for reference (do not change it):
```c
/* common.h - shared helpers for every kernel program.
 * Nothing here is parallel: timing, deterministic input generation,
 * argument parsing and the one-line result report the harness parses. */
#ifndef COMMON_H
#define COMMON_H

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/* Wall-clock seconds from a monotonic clock (unaffected by clock changes). */
static inline double now_sec(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return (double)t.tv_sec + (double)t.tv_nsec * 1e-9;
}

/* xorshift64: tiny deterministic generator, identical on Linux and macOS,
 * so every run and every LLM variant gets exactly the same input data. */
static uint64_t rng_state = 88172645463325252ULL;
static inline void rng_seed(uint64_t s) { rng_state = s ? s : 1; }
static inline uint64_t rng_next(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 7;
    rng_state ^= rng_state << 17;
    return rng_state;
}
/* Uniform double in [0, 1): top 53 bits of the generator. */
static inline double rng_unit(void) {
    return (double)(rng_next() >> 11) * (1.0 / 9007199254740992.0);
}

static inline long arg_long(int argc, char **argv, int i, long def) {
    return argc > i ? atol(argv[i]) : def;
}

static inline void *xmalloc(size_t n) {
    void *p = malloc(n);
    if (!p) { fprintf(stderr, "out of memory (%zu bytes)\n", n); exit(1); }
    return p;
}

/* One machine-readable line per run; the harness parses exactly this. */
static inline void report(const char *name, double secs, double checksum) {
    printf("kernel=%s time_s=%.6f checksum=%.12e\n", name, secs, checksum);
}

#endif

```

Program to parallelize:
```c
/* k01_saxpy: y = a*x + y, repeated. UNIFORM cost per iteration, memory-bound. */
#include "common.h"

/* === KERNEL BEGIN === */
static void kernel(long n, int reps, double a, const double *x, double *y) {
    for (int r = 0; r < reps; r++)
        for (long i = 0; i < n; i++)
            y[i] = a * x[i] + y[i];
}
/* === KERNEL END === */

int main(int argc, char **argv) {
    long n = arg_long(argc, argv, 1, 20000000);
    int reps = (int)arg_long(argc, argv, 2, 20);
    double *x = xmalloc(n * sizeof *x), *y = xmalloc(n * sizeof *y);
    rng_seed(1);
    for (long i = 0; i < n; i++) { x[i] = rng_unit(); y[i] = rng_unit(); }

    double t0 = now_sec();
    kernel(n, reps, 0.5, x, y);
    double t1 = now_sec();

    double sum = 0.0;
    for (long i = 0; i < n; i++) sum += y[i];
    report("saxpy", t1 - t0, sum);
    free(x); free(y);
    return 0;
}

```

message.content:
Looking at this kernel: `y[i] = a*x[i] + y[i]` repeated `reps` times.

**Key observation:** This kernel has a *loop-carried dependency* across repetitions at each index `i`. Each iteration `r` reads `y[i]` and writes `y[i]`. Across `r`, `y[i]` is read and written sequentially. So the `r`-loop cannot be reordered - `y[i]` for a given `i` must be updated in order.

**What CAN be parallelized:** The inner loop over `i`. Different `i` values are completely independent. So parallelize the `i` loop, keep the `r` loop serial.

**Approach:**
- Parallelize over `i` with `#pragma omp parallel for` on the inner loop.
- Only pay for the parallel-region setup once (not per rep) using `#pragma omp parallel` outside and a `#pragma omp for` inside the `r` loop.
- Schedule choice: this is a uniform memory-bound loop, so `static` scheduling is ideal (contiguous chunks, minimal overhead, good prefetching). `schedule(static)` with default chunk = n/nthreads is fine.

**Tuning for M4's asymmetric cores:** The OS places threads on P/E cores arbitrarily. On such a small (default ~n/num_threads) chunk and memory-bound work, `schedule(static)` gives the least overhead. Writes to `y[i]` are strictly per-thread without false sharing concerns once chunked — but to be safe against false sharing at chunk boundaries, `static` with equal contiguous chunks means boundaries only touch a few cache lines. Fine.

I'll factor `reps` into a single pass using precomputed constant `a` is not possible (dependency), so keep the outer `r` loop serial.

```c
/* k01_saxpy: y = a*x + y, repeated. UNIFORM cost per iteration, memory-bound. */
#include "common.h"
#include <omp.h>

/* === KERNEL BEGIN === */
static void kernel(long n, int reps, double a, const double *x, double *y) {
    #pragma omp parallel
    {
        for (int r = 0; r < reps; r++) {
            #pragma omp for schedule(static) nowait
            for (long i = 0; i < n; i++)
                y[i] = a * x[i] + y[i];
            /* implicit barrier between reps keeps y consistent for next r */
        }
    }
}
/* === KERNEL END === */

int main(int argc, char **argv) {
    long n = arg_long(argc, argv, 1, 20000000);
    int reps = (int)arg_long(argc, argv, 2, 20);
    double *x = xmalloc(n * sizeof *x), *y = xmalloc(n * sizeof *y);
    rng_seed(1);
    for (long i = 0; i < n; i++) { x[i] = rng_unit(); y[i] = rng_unit(); }

    double t0 = now_sec();
    kernel(n, reps, 0.5, x, y);
    double t1 = now_sec();

    double sum = 0.0;
    for (long i = 0; i < n; i++) sum += y[i];
    report("saxpy", t1 - t0, sum);
    free(x); free(y);
    return 0;
}
```

Note on correctness: I used `nowait` on the `omp for` — replacing the implicit barrier at the end of the `for` with the one at the end of the `r`-iteration body is fine because all threads must finish `rep r`'s writes to `y` before any thread starts `rep r+1`'s reads. The loop body has no explicit barrier, but the next iteration's `#pragma omp for` is a worksharing construct whose default delimiter includes an implicit barrier only at its **end**, not start. To be strictly correct across reps (since rep `r+1` reads `y[i]` written by rep `r` — but each thread always processes its *same* `i` indices across reps with `schedule(static)`), no barrier is actually needed between reps: each thread touches the same partition of `y` every rep, so there's no cross-thread dependency. Hence `nowait` is safe here.
